// n8n Code node (final)

// Extract input
const input = $input.first().json;
const body = input.body || input;

// UUID (from previous node, optional)
const uuid = input.uuid || body.uuid || 'no_uuid';

// team_id for internal scoping (DO NOT return)
const teamId = body.team_id;

// User name from Webhook node (snake_case source)
const userName = $('Webhook').first().json?.body?.user_name ?? 'Bilinmeyen Kullanıcı';

// Optional user_id (DO NOT return unless you want)
const userId = body.user_id ?? null;

// session_id (optional) - not returned
const sessionId = body.session_id
  ? body.session_id
  : `report_team_${teamId}_user_${userId}_uuid_${uuid}`;

// Validate required fields (teamId required for scoping)
if (!teamId) {
  throw new Error('team_id is required');
}

// Get report payload (array or object)
const reportRaw = Array.isArray(body) ? body : (body.report ?? body);

// Recursively remove keys from an object/array (team_id should never leak)
function stripKeysDeep(value, keysToRemove = new Set(['team_id', 'teamId'])) {
  if (Array.isArray(value)) return value.map((v) => stripKeysDeep(v, keysToRemove));
  if (value && typeof value === 'object') {
    const out = {};
    for (const [k, v] of Object.entries(value)) {
      if (keysToRemove.has(k)) continue;
      out[k] = stripKeysDeep(v, keysToRemove);
    }
    return out;
  }
  return value;
}

const report = stripKeysDeep(reportRaw);

// Role clarification to prevent "userName = staff" confusion
const roleRules = `ÖNEMLİ ROL AYRIMI KURALI:
- Raporu talep eden kişi (${userName}) bir yönetici/yetkili kişidir.
- Raporu talep eden kişi ASLA personel olarak değerlendirilmez.
- Rapor içinde geçen isimler yalnızca operasyonel verilerde geçen personellerdir.
- Raporu talep eden kişi hakkında performans, eksiklik, görüşme veya aksiyon önerisi üretme.
- "Personel ile görüşme" gibi ifadeler yalnızca gerçek operasyon personelleri için kullanılabilir.
- Eğer raporda geçen tek isim ${userName} ise: Bu ismi yönetici kabul et; kişi bazlı performans yorumu yapma, sürece odaklan.`;

// Build chat input
const chatInput =
`Kullanıcı (Yetkili): ${userName}

${roleRules}

## Görev
Aşağıdaki raporu analiz et ve yönetici seviyesinde danışmanlık çıktısı üret.

## Beklenti
- Bu bir personel karşılaştırma raporudur; personelleri güçlü/zayıf yönleriyle kıyasla.
- Rapor dönemini baz alarak ay bazında özet çıkar.
- “Beklemede / Teklif / Tamamlandı / İptal” akışında tıkanan noktayı bul.
- Tahmini toplam tutar ile gerçekleşen tutar arasındaki farkı yorumla.
- En az 5 kök neden hipotezi yaz ve her biri için çözüm öner.
- Kısmi dönem olan ayları tam aylarla doğrudan kıyaslama; aynı ay içinde kıyas yap, gerekirse gün başına normalize et.
- 0–7 gün, 7–30 gün, 30–90 gün aksiyon planı çıkar.
- Çıktıyı System Message’daki şablona göre yaz.
- Rapor verisini yanıtta tekrar etme; sadece özet, kıyas ve aksiyonları yaz.

Rapor (JSON):
${JSON.stringify(report, null, 2)}`;

// Return ONLY what the AI Agent needs
return [
  {
    json: {
      chatInput
      // sessionId intentionally not returned
      // teamId intentionally not returned
      // userId intentionally not returned
    }
  }
];

// INPUT: $json.output (veya $json.text) içinde "\n" stringleri olan metin
const raw = $json.output ?? $json.text ?? $json.chatInput ?? '';

const cleaned = String(raw)
  // literal "\r\n" ve "\n" stringlerini gerçek newline'a çevir
  .replace(/\\r\\n/g, '\n')
  .replace(/\\n/g, '\n')
  // bazı durumlarda kaçışlı tırnaklar gelebilir
  .replace(/\\"/g, '"')
  .replace(/\\'/g, "'")
  // gereksiz fazla boş satırları toparla
  .replace(/\n{3,}/g, '\n\n')
  // satır sonlarındaki fazla boşlukları temizle
  .replace(/[ \t]+\n/g, '\n')
  .trim();

return [
  {
    json: {
      output: cleaned
    }
  }
];

// Markdown node'un destination key'i "html" ise:
const rawHtml = $json.html ?? '';

// HTML içindeki literal \n gibi kaçışları temizle
let html = String(rawHtml)
  .replace(/\\r\\n/g, '')
  .replace(/\\n/g, '')
  .replace(/\\t/g, '')
  .trim();

// Tag arası boşlukları hafif toparla (opsiyonel)
html = html.replace(/>\s+</g, '><');

return [{ json: { html } }];
